import csv, json, os
status_map = {'A': 'active', 'C': 'closed', 'P': 'pending'}
with open('/app/data/active.csv', newline='') as f:
    records = [
        {'id': row['id'], 'name': row['first_name'] + ' ' + row['last_name'], 'status': status_map[row['status']]}
        for row in csv.DictReader(f)
    ]
os.makedirs('/app/out', exist_ok=True)
with open('/app/out/migrated.json', 'w') as f:
    json.dump(records, f, indent=2)
    f.write('\n')
